// Fetch Translatable EN Questions stage -- calls the read-only
// /api/internal/questions/for-translation endpoint (default statuses:
// PUBLISHED,PENDING_REVIEW -- REJECTED questions are never translated), then
// applies two client-side filters:
//
// 1) Skip source == "MANUAL" -- this project has always authored MANUAL questions
//    as matched EN+TR pairs from the start (confirmed: ids 1-10 are exactly 5
//    EN + 5 TR MANUAL rows), so a MANUAL EN question already has a real,
//    hand-written TR sibling. Translating it again would create a redundant,
//    machine-phrased duplicate that the fuzzy Duplicate Check stage cannot
//    always catch (different wording of the same fact can score below the
//    Jaccard threshold -- observed for real with 3 baseline questions before
//    this filter existed). The fuzzy dedup check later in the pipeline still
//    runs as a safety net for everything else.
// 2) ONLY_IDS below -- a small, hand-curated allow-list for a single controlled
//    run (same "never all topics/questions blindly" philosophy as Topic
//    Selection in the generation workflow). Set to null/[] to translate every
//    eligible (non-MANUAL) EN question.
const ONLY_IDS = [46, 48];

const baseUrl = $env.QUESTION_INGEST_BASE_URL || "http://localhost:8080";
const apiKey = $env.QUIZ_INGEST_API_KEY;

const questions = await this.helpers.httpRequest({
  method: "GET",
  url: `${baseUrl}/api/internal/questions/for-translation?language=en`,
  headers: { "X-Api-Key": apiKey },
  json: true,
});

const eligible = questions.filter(q => q.source !== "MANUAL");
const scoped = (ONLY_IDS && ONLY_IDS.length > 0) ? eligible.filter(q => ONLY_IDS.includes(q.id)) : eligible;

return scoped.map(q => ({ json: q }));

// Build Translation Requests stage -- builds one grounded translation prompt per
// EN question, carrying the full original question (id, topicSlug, type,
// difficulty, codeSnippet, codeLanguage, options with their correct flags)
// forward under "original" -- type/difficulty/codeSnippet/topic are NEVER re-read
// from the LLM's output later, only from this original object, so the model
// cannot change them even if it tried.
function buildPrompt(q) {
  const optionsList = q.options.map((o, i) => `${i + 1}. ${o.optionText}`).join("\n");
  const codeBlock = q.codeSnippet ? `Code (do NOT translate, shown here only for context):\n${q.codeSnippet}\n\n` : "";
  return `You are translating an existing, already-approved English quiz question about Java into natural, fluent Turkish for a Java learning platform. This is a TRANSLATION task, not a new-question-generation task -- do not add, remove, or change any technical fact.

Rules:
- Translate ONLY natural-language prose (the question text, the explanation, and the option texts).
- NEVER translate Java identifiers, keywords, method/class/type names, or code fragments that appear inline in the text (e.g. enum, valueOf(), ordinal(), class/method names) -- keep them exactly as written.
- Do NOT change which options are correct or incorrect -- you are only translating text, not judging correctness.
- Do NOT add, remove, or reorder options.
- Do NOT change the meaning, difficulty, or technical content of the question.
- Use natural, idiomatic Turkish for an educational Java platform, the way an existing Turkish Java course on this platform would phrase it.

Original English question (type: ${q.type}, difficulty: ${q.difficulty}):
Question: ${q.question}
${codeBlock}Explanation: ${q.explanation}
Options (in order):
${optionsList}

Return ONLY a JSON object (no prose, no markdown fences) with exactly this shape:
{"question": "...", "explanation": "...", "options": ["...", "...", ...]}
The "options" array must have exactly ${q.options.length} strings, in the SAME order as the original options above.`;
}

return $input.all().map(item => ({
  json: {
    original: item.json,
    prompt: buildPrompt(item.json),
  }
}));

// Parse Translation stage -- reads the OpenAI Chat Completions response shape and
// extracts the translated {question, explanation, options[]}. The original question
// (topicSlug/type/difficulty/codeSnippet/codeLanguage/options-with-correct-flags) is
// recovered via itemMatching against Build Translation Requests, since the real HTTP
// Request node replaces item.json with the raw API response (same lesson as the
// generation pipeline's Faz 147 fix).
const results = [];
const inputItems = $input.all();
for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i];
  const original = $('Build Translation Requests').itemMatching(i).json.original;

  let translated = null;
  let parseError = null;
  try {
    const raw = item.json.choices && item.json.choices[0] && item.json.choices[0].message && item.json.choices[0].message.content;
    if (!raw) throw new Error("no message content in LLM response");
    translated = JSON.parse(raw);
  } catch (e) {
    parseError = e.message;
  }

  results.push({ json: { original, translated, parseError } });
}
return results;

// Validate Translation stage -- deterministic, structural only. Confirms the
// translation kept the exact same option COUNT as the original (order is assumed
// preserved per the prompt's explicit instruction) and that nothing looks empty or
// suspiciously untranslated (identical to the English source). Does NOT re-validate
// type/difficulty/codeSnippet/topic -- those are never taken from the model's output
// in the first place (see Submit Valid Translations), so there is nothing to check.
function normalize(text) {
  return (text || "").toLowerCase().replace(/[^\w\s]/g, "").replace(/\s+/g, " ").trim();
}

// A real transport-level corruption was observed with a live OpenAI response: one
// item's Turkish text came back with its UTF-8 bytes mangled into CJK-range
// characters (e.g. "icin" -> "i\u83bdin"). Turkish text should never legitimately
// contain CJK Unified Ideographs -- this is a cheap, reliable guard against that
// specific failure mode recurring silently.
const CJK_RANGE = /[\u4e00-\u9fff]/;
function containsUnexpectedCjk(text) {
  return typeof text === "string" && CJK_RANGE.test(text);
}

return $input.all().map(item => {
  const { original, translated, parseError } = item.json;
  const reasons = [];

  if (parseError) {
    reasons.push("LLM output parse error: " + parseError);
  } else if (!translated || typeof translated !== "object") {
    reasons.push("translated output is not a JSON object");
  } else {
    if (!translated.question || typeof translated.question !== "string" || translated.question.trim().length < 5) {
      reasons.push("translated question missing or too short");
    }
    if (!translated.explanation || typeof translated.explanation !== "string" || translated.explanation.trim().length < 5) {
      reasons.push("translated explanation missing or too short");
    }
    if (!Array.isArray(translated.options) || translated.options.length !== original.options.length) {
      reasons.push(`translated options count (${translated.options ? translated.options.length : 0}) does not match original (${original.options.length})`);
    } else if (translated.options.some(o => !o || typeof o !== "string" || !o.trim())) {
      reasons.push("empty translated option text");
    }
    if (translated.question && normalize(translated.question) === normalize(original.question)) {
      reasons.push("translated question text is identical to the English source -- looks untranslated");
    }
    if (containsUnexpectedCjk(translated.question) || containsUnexpectedCjk(translated.explanation)
        || (Array.isArray(translated.options) && translated.options.some(containsUnexpectedCjk))) {
      reasons.push("translated text contains unexpected CJK characters -- likely a transport/encoding corruption, not a real translation");
    }
  }

  return { json: { ...item.json, validation: { passed: reasons.length === 0, reasons } } };
});

// Duplicate Check stage -- same normalized exact-match + Jaccard word-overlap
// technique as the generation pipeline's Duplicate Check, applied against the REAL
// TR pool for this topic (via /api/internal/questions/existing?language=tr, all
// statuses -- a PENDING_REVIEW or REJECTED TR question still counts as "already
// tried"). Comparable text is translated-question + ORIGINAL codeSnippet (code is
// never translated, so it stays identical across languages -- same fix as Faz 147's
// CODE_OUTPUT false-positive, applied here from the start).
function normalize(text) {
  return (text || "").toLowerCase().replace(/[^\w\s]/g, "").replace(/\s+/g, " ").trim();
}
function tokenSet(text) {
  return new Set(normalize(text).split(" ").filter(Boolean));
}
function jaccard(a, b) {
  const inter = [...a].filter(x => b.has(x)).length;
  const union = new Set([...a, ...b]).size;
  return union === 0 ? 0 : inter / union;
}
// Same boilerplate-overlap false-positive fix as the generation pipeline's
// Duplicate Check (Faz 148), refined further after a real run showed "last line"
// alone picks up a near-empty closing brace for snippets wrapped in a main()
// method. Only the last line with meaningful content once braces/parens/
// semicolons are stripped is compared, so the comparison lands on the actual
// statement under test regardless of trailing braces.
function comparableText(question, codeSnippet) {
  if (!codeSnippet) return question;
  const lines = codeSnippet.split("\n").map(l => l.trim()).filter(Boolean);
  const meaningfulLines = lines.filter(l => l.replace(/[{}();]/g, "").trim().length > 0);
  const distinctiveLine = meaningfulLines.length > 0
    ? meaningfulLines[meaningfulLines.length - 1]
    : (lines.length > 0 ? lines[lines.length - 1] : codeSnippet);
  return `${question} ${distinctiveLine}`;
}

const JACCARD_THRESHOLD = 0.6;
const baseUrl = $env.QUESTION_INGEST_BASE_URL || "http://localhost:8080";
const apiKey = $env.QUIZ_INGEST_API_KEY;

const items = $input.all().filter(i => i.json.validation && i.json.validation.passed);
const skipped = $input.all().filter(i => !i.json.validation || !i.json.validation.passed);

const existingCache = {};
const results = [];

for (const item of items) {
  const { original, translated } = item.json;
  const topicSlug = original.topicSlug;
  const key = topicSlug + "::tr";
  if (!(key in existingCache)) {
    existingCache[key] = await this.helpers.httpRequest({
      method: "GET",
      url: `${baseUrl}/api/internal/questions/existing?topicSlug=${encodeURIComponent(topicSlug)}&language=tr`,
      headers: { "X-Api-Key": apiKey },
      json: true,
    });
  }

  const newText = comparableText(translated.question, original.codeSnippet);
  const newTokens = tokenSet(newText);
  const newNorm = normalize(newText);
  let match = null;

  for (const ex of existingCache[key]) {
    if (normalize(ex.question) === newNorm) { match = { id: ex.id, reason: "exact match (existing TR)" }; break; }
    const sim = jaccard(newTokens, tokenSet(ex.question));
    if (sim >= JACCARD_THRESHOLD) { match = { id: ex.id, reason: `word-overlap ${sim.toFixed(2)} (existing TR)` }; break; }
  }

  if (!match) {
    for (const accepted of results) {
      if (accepted.json.original.topicSlug !== topicSlug) continue;
      const acceptedText = comparableText(accepted.json.translated.question, accepted.json.original.codeSnippet);
      const sim2 = jaccard(newTokens, tokenSet(acceptedText));
      const norm2 = normalize(acceptedText);
      if (newNorm === norm2 || sim2 >= JACCARD_THRESHOLD) { match = { id: "batch:" + acceptedText.slice(0, 40), reason: "within-batch duplicate" }; break; }
    }
  }

  results.push({ json: { ...item.json, duplicateCheck: { isDuplicate: !!match, matchedId: match ? match.id : null, reason: match ? match.reason : null } } });
}

for (const s of skipped) {
  results.push({ json: { ...s.json, duplicateCheck: { isDuplicate: false, matchedId: null, reason: "skipped (failed validation)" } } });
}

return results;

// Submit Valid Translations stage -- POSTs only items that passed both Validate
// Translation and Duplicate Check to the EXISTING /api/internal/questions/ingest
// endpoint. type/difficulty/codeSnippet/codeLanguage/topicSlug and each option's
// `correct` flag are copied VERBATIM from the ORIGINAL EN question -- never from the
// model's translated output -- so a translation can only ever change question text/
// explanation text/option text, structurally never the answer, structure, difficulty,
// type, code, or topic (per the requirement that a translation must not alter any of
// those). source is always "OPENAI", no status field -- the API forces PENDING_REVIEW
// regardless. Non-qualifying items pass through tagged with a skip reason instead of
// being dropped, so Record Results can still summarize the full batch.
const baseUrl = $env.QUESTION_INGEST_BASE_URL || "http://localhost:8080";
const apiKey = $env.QUIZ_INGEST_API_KEY;
const results = [];

for (const item of $input.all()) {
  const { original, translated, validation, duplicateCheck } = item.json;
  const submittable = validation && validation.passed && duplicateCheck && !duplicateCheck.isDuplicate;

  if (!submittable) {
    results.push({ json: { ...item.json, submission: { attempted: false, success: false, reason: (!validation || !validation.passed) ? "failed validation" : "duplicate" } } });
    continue;
  }

  const optionsPayload = original.options.map((o, i) => ({ optionText: translated.options[i], correct: o.correct }));

  try {
    const response = await this.helpers.httpRequest({
      method: "POST",
      url: `${baseUrl}/api/internal/questions/ingest`,
      headers: { "X-Api-Key": apiKey, "Content-Type": "application/json" },
      body: {
        topicSlug: original.topicSlug,
        language: "tr",
        type: original.type,
        difficulty: original.difficulty,
        source: "OPENAI",
        question: translated.question,
        codeSnippet: original.codeSnippet,
        codeLanguage: original.codeLanguage,
        explanation: translated.explanation,
        options: optionsPayload,
      },
      json: true,
    });
    results.push({ json: { ...item.json, submission: { attempted: true, success: true, id: response.id, status: response.status } } });
  } catch (e) {
    results.push({ json: { ...item.json, submission: { attempted: true, success: false, reason: e.message } } });
  }
}
return results;

// Record Results stage -- final summary of the whole translation run.
const items = $input.all().map(i => i.json);
const summary = {
  totalCandidates: items.length,
  validationFailed: items.filter(i => !i.validation || !i.validation.passed).length,
  duplicatesSkipped: items.filter(i => i.validation && i.validation.passed && i.duplicateCheck && i.duplicateCheck.isDuplicate).length,
  submitted: items.filter(i => i.submission && i.submission.success).length,
  submissionFailed: items.filter(i => i.submission && i.submission.attempted && !i.submission.success).length,
  details: items.map(i => ({
    originalId: i.original.id,
    topicSlug: i.original.topicSlug,
    translatedQuestion: i.translated ? (i.translated.question || "").slice(0, 70) : null,
    validationPassed: i.validation ? i.validation.passed : false,
    validationReasons: i.validation ? i.validation.reasons : [],
    isDuplicate: i.duplicateCheck ? i.duplicateCheck.isDuplicate : false,
    duplicateReason: i.duplicateCheck ? i.duplicateCheck.reason : null,
    submitted: i.submission ? i.submission.success : false,
    submittedId: i.submission ? i.submission.id : null,
  })),
};
return [{ json: summary }];
